"""Bounded character-prefix-aware DataFrame column permutation search."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Reorders columns using bounded exact character-prefix candidate selection."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source frame and the latest row-specific orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert one cell to the evaluator-compatible string representation."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the common-prefix length using bounded C-level slice comparisons."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings):
        """Compute exact sorted-adjacent character-Trie reuse for row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column names to their source positions."""
        result = {}
        for i, name in enumerate(columns):
            result.setdefault(str(name), []).append(i)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build mandatory merge blocks with deterministic union-find semantics."""
        parent = list(range(width))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(v) for v in groups.values()), key=lambda v: v[0])

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Topologically repair a preference while preserving merges and dependencies."""
        positions = cls._positions(columns)
        edges, seen = [], set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                edges.append((a, b))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for a, b in zip(block, block[1:]):
                add(a, b)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for a, b in edges:
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {v: i for i, v in enumerate(preference)}
        heap = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(heap)

        answer = []
        while heap:
            _, node = heapq.heappop(heap)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, width + nxt), nxt))

        return answer if len(answer) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Compute length-weighted whole-value repetition statistics per column."""
        _, width = text.shape
        result = []
        for col in range(width):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))
        return result

    @classmethod
    def _projected_path_orders(cls, text, stats, blocks):
        """Construct a directed block path from exact two-block concatenation gains.

        Each directed edge is scored from the exact sorted LCP objective of the
        projected A-then-B strings, less the two individual block scores.  At
        most 18 active blocks and one edge evaluation per ordered pair are used.
        """
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        rows = text.shape[0]
        mass = [sum(stats[c][0] for c in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:18]

        projected = {}
        singles = {}
        for i in active:
            cols = blocks[i]
            values = ["".join(text[r, c] for c in cols) for r in range(rows)]
            projected[i] = values
            singles[i] = cls._score(values)

        edges = []
        for a in active:
            for b in active:
                if a == b:
                    continue
                combined = [
                    projected[a][r] + projected[b][r]
                    for r in range(rows)
                ]
                gain = cls._score(combined) - singles[a] - singles[b]
                edges.append((gain, a, b))

        # Greedily form a directed path forest, forbidding cycles and
        # multiple predecessors/successors.
        edges.sort(key=lambda x: (-x[0], x[1], x[2]))
        successor = {}
        predecessor = {}

        def reaches(start, target):
            """Check whether target is reachable through currently selected links."""
            node = start
            seen = set()
            while node in successor and node not in seen:
                if node == target:
                    return True
                seen.add(node)
                node = successor[node]
            return node == target

        for gain, a, b in edges:
            if gain <= 0:
                continue
            if a in successor or b in predecessor:
                continue
            if reaches(b, a):
                continue
            successor[a] = b
            predecessor[b] = a

        # Extract chains, then append inactive and isolated blocks by repetition mass.
        starts = [i for i in active if i not in predecessor]
        starts.sort(key=lambda i: (-mass[i], blocks[i][0]))
        used = set()
        block_order = []

        for start in starts:
            node = start
            while node not in used:
                used.add(node)
                block_order.append(node)
                node = successor.get(node)
                if node is None:
                    break

        remainder = sorted(
            (i for i in range(len(blocks)) if i not in used),
            key=lambda i: (-mass[i], blocks[i][0]),
        )
        block_order.extend(remainder)
        return [[c for i in block_order for c in blocks[i]]]

    @staticmethod
    def _serialize(text, order):
        """Serialize each row under one column permutation without altering cells."""
        return [
            "".join(text[row, col] for col in order)
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized keys and materialize exact source values."""
        row_order = sorted(range(len(serialized)), key=lambda r: (serialized[r], r))
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for out_row, src_row in enumerate(row_order):
            values[out_row, :] = [source[src_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        return (
            pd.DataFrame(
                values,
                index=df.index.take(row_order),
                columns=list(df.columns),
            ),
            public_orders,
        )

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate global and directed-path column candidates and return the best."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [self._cell_string(v) for v in source[:, col]]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        baseline = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline]
        preferences.extend(self._projected_path_orders(text, stats, blocks))

        best_score = -1
        best_order = baseline
        best_serialized = None

        for preference in preferences[:3]:
            order = self._repair(
                width, preference, columns, one_way_dep, blocks
            )
            serialized = self._serialize(text, order)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_order = order
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_order, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

