        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        pos = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left, right = pos.get(str(pair[0]), []), pos.get(str(pair[1]), [])
