"""Bounded character-prefix-aware DataFrame column permutation search."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Reorders columns using bounded exact character-prefix candidate selection."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source frame and the latest row-specific orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert one cell to the evaluator-compatible string representation."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the common-prefix length using bounded C-level slice comparisons."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings):
        """Compute exact sorted-adjacent character-Trie reuse for row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column names to their source positions."""
        result = {}
        for i, name in enumerate(columns):
            result.setdefault(str(name), []).append(i)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build mandatory merge blocks with deterministic union-find semantics."""
        parent = list(range(width))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(v) for v in groups.values()), key=lambda v: v[0])

